if [[ "$SESSION_ACTIVE" == "1" ]]; then
  echo "LIVE_WS_GATE=HARD max=180s freshness<=15s fatal=1"
  LIVE_OK=0
  LIVE_WS_STATUS="FAIL"
  for i in $(seq 1 60); do
    J="$(curl -fsS --connect-timeout 2 --max-time 4 http://127.0.0.1:${HOST_PORT}/api/health 2>/dev/null || true)"
    if [[ -n "$J" ]]; then
      printf '%s' "$J" > "$TMP/live.json"
      LINE="$(python3 - "$TMP/live.json" <<'PYLIVE'
import sys,json,time
h=json.load(open(sys.argv[1]));w=h.get('ws') or {};f=h.get('feed') or {};s=f.get('session') or {};now=time.time()
connected=bool(w.get('connected'));tr=int(w.get('trade_registered') or 0);krx=int(w.get('krx_registered') or 0);nxt=int(w.get('nxt_registered') or 0);lt=float(w.get('last_trade_at') or 0);age=(now-lt) if lt else 1e9
venue_ok=(not s.get('krx') or krx>0) and (not s.get('nxt') or nxt>0)
err=str(w.get('last_error') or '')
ok=connected and tr>0 and venue_ok and age<=15 and not err
print(('PASS' if ok else 'WAIT')+f" connected={connected} trade={tr} krx={krx} nxt={nxt} age={age:.1f}s stage={w.get('diag_stage')} attempt={w.get('attempt_id')} error={err[:80]}")
PYLIVE
)"
      LIVE_WS_LAST_LINE="$LINE"; echo "LIVE_WS[$i] $LINE"
      if [[ "$LINE" == PASS* ]]; then LIVE_OK=1; LIVE_WS_STATUS="PASS"; break; fi
    fi
    sleep 3
  done
  if [[ $LIVE_OK -ne 1 ]]; then
    DIAG="$APP_DIR/deployments/NOVA-${VERSION}-${STAMP}-LIVE-WS-FAILED.diag"
    {
      echo "status=FAILED"; echo "reason=ACTIVE_SESSION_LIVE_WS_NOT_PROVEN"; echo "last_line=$LIVE_WS_LAST_LINE"; echo "observed_at=$(date -Is)"
